CREATE TABLE IF NOT EXISTS `dealer_data` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `dealership` varchar(191) NOT NULL,
  `data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`data`)),
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_dealership` (`dealership`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;

CREATE TABLE IF NOT EXISTS `dealer_records` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `dealership` varchar(191) NOT NULL,
  `time` bigint(20) NOT NULL,
  `category` varchar(191) DEFAULT NULL,
  `data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`data`)),
  PRIMARY KEY (`id`),
  KEY `idx_dealership_time` (`dealership`,`time`),
  KEY `idx_dealership_category` (`dealership`,`category`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;

CREATE TABLE IF NOT EXISTS `dealer_records_buybacks` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `dealership` varchar(191) NOT NULL,
  `data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`data`)),
  PRIMARY KEY (`id`),
  KEY `idx_dealership` (`dealership`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;

CREATE TABLE IF NOT EXISTS `dealer_showrooms` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `dealership` varchar(191) NOT NULL,
  `data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`data`)),
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_dealership` (`dealership`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;

CREATE TABLE IF NOT EXISTS `dealer_stock` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `dealership` varchar(191) NOT NULL,
  `vehicle` varchar(191) NOT NULL,
  `model_type` varchar(191) DEFAULT NULL,
  `quantity` int(11) NOT NULL DEFAULT 0,
  `data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`data`)),
  `last_stocked` bigint(20) DEFAULT NULL,
  `last_purchase` bigint(20) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_dealership_vehicle` (`dealership`,`vehicle`)
) ENGINE=InnoDB AUTO_INCREMENT=307 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;

